package lt.pinet.memorystring.demo;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import android.view.accessibility.AccessibilityNodeInfo;import android.graphics.Bitmap;import org.json.*;import java.io.*;import java.util.concurrent.*;
/** Exercises the actual Android document picker with an owned, unique QA backup. */
public final class FileJourney extends Instrumentation{
 private MainActivity activity;private WebView web;private File dir;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private Object js(String s)throws Exception{CountDownLatch l=new CountDownLatch(1);String[]r={null};runOnMainSync(()->web.evaluateJavascript(s,v->{r[0]=v;l.countDown();}));if(!l.await(10,TimeUnit.SECONDS))throw new Exception("JS timeout");return new JSONTokener(r[0]).nextValue();}
 private void waitFor(String s,int seconds)throws Exception{long end=System.currentTimeMillis()+seconds*1000;while(System.currentTimeMillis()<end){try{if(Boolean.TRUE.equals(js(s)))return;}catch(Exception ignored){}Thread.sleep(200);}throw new Exception("Wait failed: "+s);}
 private AccessibilityNodeInfo find(AccessibilityNodeInfo n,String text){if(n==null)return null;if(n.getPackageName()!=null&&n.getPackageName().toString().contains("documentsui")&&n.isEnabled()&&n.getText()!=null&&n.getText().toString().equalsIgnoreCase(text))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo f=find(n.getChild(i),text);if(f!=null)return f;}return null;}
 private AccessibilityNodeInfo pickerRoot(){for(android.view.accessibility.AccessibilityWindowInfo window:getUiAutomation().getWindows()){AccessibilityNodeInfo root=window.getRoot();if(root!=null&&root.getPackageName()!=null&&root.getPackageName().toString().contains("documentsui"))return root;}return getUiAutomation().getRootInActiveWindow();}
 private void tap(String selector)throws Exception{JSONObject r=new JSONObject((String)js("JSON.stringify((()=>{const e=document.querySelector("+JSONObject.quote(selector)+");const r=e.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,width:innerWidth}})())"));int[] pos=new int[2];runOnMainSync(()->web.getLocationOnScreen(pos));float scale=web.getWidth()/(float)r.getDouble("width"),x=pos[0]+(float)r.getDouble("x")*scale,y=pos[1]+(float)r.getDouble("y")*scale;long t=SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(t,t,0,x,y,0),up=android.view.MotionEvent.obtain(t,t+60,1,x,y,0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(down,true);getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();}
 private void shot(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream o=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
 @Override public void onStart(){boolean ok=false;String failure="",filename="";try{android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;getUiAutomation().setServiceInfo(info);activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));java.lang.reflect.Field f=MainActivity.class.getDeclaredField("web");f.setAccessible(true);web=(WebView)f.get(activity);dir=new File(getTargetContext().getFilesDir(),"qa-current");dir.mkdirs();waitFor("typeof route==='string' && document.fonts.status==='loaded'",20);js("go('library',{reset:['home']})");waitFor("document.querySelector('#project-list .project-main-action')!==null",10);js("document.querySelector('#project-list .project-main-action').click()");waitFor("route==='guide'||route==='layer'||route==='completed'",10);
 js("window.msQaBackup=validateProject({...active,id:uuid()});window.msQaExportOk=null;window.msQaSavedExport=window.msExportResult;window.msExportResult=(ok,cancelled)=>{window.msQaExportOk=ok;window.msQaSavedExport(ok,cancelled)};download(window.msQaBackup)");filename="MemoryString-"+((String)js("window.msQaBackup.id")).substring(0,8)+".json";
 AccessibilityNodeInfo save=null;long end=System.currentTimeMillis()+10000;while(save==null&&System.currentTimeMillis()<end){Thread.sleep(200);save=find(pickerRoot(),"Save");}shot("23-system-export-picker");if(save==null)throw new Exception("The system Save control was not accessible");if(!save.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new Exception("System Save did not accept the click");waitFor("window.msQaExportOk===true",15);shot("24-export-success");
 // Import the exact file the system just wrote by selecting its visible filename.
 js("go('settings')");tap("#settings [data-act=import]");AccessibilityNodeInfo file=null;end=System.currentTimeMillis()+10000;while(file==null&&System.currentTimeMillis()<end){Thread.sleep(200);file=find(getUiAutomation().getRootInActiveWindow(),filename);}shot("25-system-import-picker");if(file==null)throw new Exception("Export succeeded; select the owned backup from the system picker to finish import");file.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.getId());Thread.sleep(400);file=find(getUiAutomation().getRootInActiveWindow(),filename);if(file==null)throw new Exception("Owned file left the picker viewport");AccessibilityNodeInfo target=file;while(target!=null&&!target.isClickable())target=target.getParent();if(target==null)throw new Exception("Import file was not selectable");android.graphics.Rect bounds=new android.graphics.Rect();file.getBoundsInScreen(bounds);if(bounds.centerY()<0||bounds.centerY()>getTargetContext().getResources().getDisplayMetrics().heightPixels)throw new Exception("Owned file is outside the visible viewport: "+bounds.toShortString());long now=SystemClock.uptimeMillis();android.view.MotionEvent d=android.view.MotionEvent.obtain(now,now,0,bounds.centerX(),bounds.centerY(),0),u=android.view.MotionEvent.obtain(now,now+60,1,bounds.centerX(),bounds.centerY(),0);d.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);u.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(d,true);getUiAutomation().injectInputEvent(u,true);d.recycle();u.recycle();Thread.sleep(500);if(Boolean.TRUE.equals(js("route==='settings'"))){target.performAction(AccessibilityNodeInfo.ACTION_FOCUS);sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_ENTER);}shot("26-after-file-selection");waitFor("active.title.endsWith(' · imported')",15);if(!Boolean.TRUE.equals(js("active.id!==window.msQaBackup.id && active.step===window.msQaBackup.step && JSON.stringify(active.layers)===JSON.stringify(window.msQaBackup.layers)")))throw new Exception("Imported sequence or position changed");shot("26-import-success");js("window.msQaImported=active.id;database('delete',window.msQaImported);activate(window.msQaBackup);go('home',{reset:[]})");ok=true;
 }catch(Exception e){failure=e.toString();try{java.lang.reflect.Field pick=MainActivity.class.getDeclaredField("picker");pick.setAccessible(true);failure+="; pickerPending="+(pick.get(activity)!=null);failure+="; app state="+js("JSON.stringify({route,sheet:document.getElementById('sheet').open,title:document.getElementById('sheet-title').textContent,message:document.getElementById('sheet-body').textContent})");shot("file-failure");}catch(Exception ignored){}}finally{try{JSONObject result=new JSONObject().put("pass",ok).put("failure",failure).put("ownedBackupFilename",filename);try(FileOutputStream f=new FileOutputStream(new File(dir,"files-journey.json"))){f.write(result.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}}catch(Exception ignored){}Bundle b=new Bundle();b.putString("result",ok?"PASS":failure);finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,b);}}
}
